#!/usr/bin/env python3
from pathlib import Path
import shutil,sys
if len(sys.argv)!=3: raise SystemExit('FAIL: usage base candidate')
base=Path(sys.argv[1]); root=Path(sys.argv[2])
if root.exists(): shutil.rmtree(root)
shutil.copytree(base,root)

# Parameters state owner
p=root/'app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java'
s=p.read_text()
old='''    public float motionV2DisplayGain = 1.0f;\n'''
new='''    public float motionV2DisplayGain = 1.0f;\n    /* IRIS_26582_SCENE_ADAPTIVE_GLOBAL_TONE_STATE\n     * Decision-only presentation state produced by MotionV2ViewfinderExposureMatcher from its\n     * existing low-resolution candidate probe. No RAW/capture/DNG owner consumes these fields.\n     */\n    public float motionV2ToneP95Guide = Float.NaN;\n    public float motionV2ToneP99Guide = Float.NaN;\n    public float motionV2TonePredictedClipFraction = 0.0f;\n    public float motionV2ToneBaseSceneWhite = 1.0f;\n    public float motionV2ToneAdaptiveSceneWhite = 1.0f;\n    public float motionV2ToneAdaptiveStrength = 0.0f;\n'''
assert s.count(old)==1
p.write_text(s.replace(old,new))

# Render: constants + shared Java tone model and adaptive scene white consumption.
p=root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java'
s=p.read_text()
s=s.replace('''    private static final float OUTPUT_EXPOSURE_SCALE = 0.80f;\n''','''    static final float OUTPUT_EXPOSURE_SCALE = 0.80f;\n    static final float IRIS_26582_TONE_START = 0.50f;\n    static final float IRIS_26582_HIGHLIGHT_TARGET = 0.97f;\n    static final float IRIS_26582_CLIP_FRACTION_START = 0.002f;\n    static final float IRIS_26582_CLIP_FRACTION_FULL = 0.025f;\n    static final float IRIS_26582_MAX_ADAPTIVE_SCENE_WHITE = 12.0f;\n    private static final float IRIS_26582_LOG_SHAPE = 6.0f;\n''',1)
anchor='''    public MotionV2Render() { super("", "MotionV2Render"); }\n    @Override public void Compile() {}\n'''
insert='''    public MotionV2Render() { super("", "MotionV2Render"); }\n    @Override public void Compile() {}\n\n    /* IRIS_26582_SHARED_GLOBAL_TONE_MODEL\n     * Single Java authority used by both the viewfinder solver and render setup. The GLSL render\n     * uses the same start/log shape/output scale; only sceneWhite is scene-adaptive.\n     */\n    static float iris26582BaseSceneWhite(float displayGain) {\n        return Math.max(1.0f, Math.min(6.0f, 0.90f * Math.max(1.0f, displayGain)));\n    }\n\n    static float iris26582MapHeadroom(float guide, float sceneWhite) {\n        if (guide <= IRIS_26582_TONE_START) return guide;\n        float whitePoint = Math.max(sceneWhite, IRIS_26582_TONE_START + 0.05f);\n        float x = iris26582Clamp((guide - IRIS_26582_TONE_START)\n                / Math.max(whitePoint - IRIS_26582_TONE_START, 1.0e-6f), 0.0f, 1.0f);\n        float shaped = (float)(Math.log(1.0 + IRIS_26582_LOG_SHAPE * x)\n                / Math.log(1.0 + IRIS_26582_LOG_SHAPE));\n        float preScaleDisplayWhite = 1.0f / OUTPUT_EXPOSURE_SCALE;\n        return IRIS_26582_TONE_START\n                + (preScaleDisplayWhite - IRIS_26582_TONE_START) * shaped;\n    }\n\n    static float iris26582AdaptiveStrength(float clippedFraction) {\n        float t = iris26582Clamp((clippedFraction - IRIS_26582_CLIP_FRACTION_START)\n                / Math.max(IRIS_26582_CLIP_FRACTION_FULL\n                        - IRIS_26582_CLIP_FRACTION_START, 1.0e-6f), 0.0f, 1.0f);\n        return t * t * (3.0f - 2.0f * t);\n    }\n\n    static float iris26582AdaptiveSceneWhite(float displayGain, float p99Guide,\n                                              float clippedFraction) {\n        float baseWhite = iris26582BaseSceneWhite(displayGain);\n        if (!Float.isFinite(p99Guide) || p99Guide <= 0.0f) return baseWhite;\n        float postP99 = p99Guide * Math.max(displayGain, 1.0e-6f);\n        if (postP99 <= baseWhite) return baseWhite;\n\n        /* Put robust P99 near 0.97 SDR, leaving the final 0.03 for rarer peaks.\n         * This is the inverse of the existing 26581 global log shoulder, not a new local operator.\n         */\n        float targetPreScale = IRIS_26582_HIGHLIGHT_TARGET / OUTPUT_EXPOSURE_SCALE;\n        float preScaleWhite = 1.0f / OUTPUT_EXPOSURE_SCALE;\n        float targetShape = iris26582Clamp((targetPreScale - IRIS_26582_TONE_START)\n                / Math.max(preScaleWhite - IRIS_26582_TONE_START, 1.0e-6f), 0.0f, 1.0f);\n        float targetX = (float)((Math.exp(targetShape * Math.log(1.0 + IRIS_26582_LOG_SHAPE)) - 1.0)\n                / IRIS_26582_LOG_SHAPE);\n        float requiredWhite = IRIS_26582_TONE_START\n                + (postP99 - IRIS_26582_TONE_START) / Math.max(targetX, 1.0e-4f);\n        requiredWhite = Math.max(baseWhite, Math.min(IRIS_26582_MAX_ADAPTIVE_SCENE_WHITE, requiredWhite));\n        float strength = iris26582AdaptiveStrength(clippedFraction);\n        return baseWhite + (requiredWhite - baseWhite) * strength;\n    }\n\n    private static float iris26582Clamp(float x, float lo, float hi) {\n        return Math.max(lo, Math.min(hi, x));\n    }\n'''
assert s.count(anchor)==1
s=s.replace(anchor,insert)
old='''        float sceneWhite = Math.max(\n                1.0f, Math.min(6.0f, 0.90f * postDisplaySensorWhite));\n'''
new='''        float baseSceneWhite = iris26582BaseSceneWhite(postDisplaySensorWhite);\n        float sceneWhite = basePipeline.mParameters.motionV2ToneAdaptiveSceneWhite;\n        if (!Float.isFinite(sceneWhite) || sceneWhite < baseSceneWhite) {\n            sceneWhite = baseSceneWhite;\n        }\n        sceneWhite = Math.min(IRIS_26582_MAX_ADAPTIVE_SCENE_WHITE, sceneWhite);\n'''
assert s.count(old)==1
s=s.replace(old,new)
old='''                + " sceneWhite=" + sceneWhite\n                + " IRIS_26515_RENDER_EXPOSURE_AUTHORITY_SPLIT=true"\n'''
new='''                + " sceneWhite=" + sceneWhite\n                + " baseSceneWhite=" + baseSceneWhite\n                + " toneP95Guide=" + basePipeline.mParameters.motionV2ToneP95Guide\n                + " toneP99Guide=" + basePipeline.mParameters.motionV2ToneP99Guide\n                + " predictedClipFraction=" + basePipeline.mParameters.motionV2TonePredictedClipFraction\n                + " adaptiveStrength=" + basePipeline.mParameters.motionV2ToneAdaptiveStrength\n                + " adaptiveHighlightTarget=" + IRIS_26582_HIGHLIGHT_TARGET\n                + " IRIS_26582_SCENE_ADAPTIVE_GLOBAL_TONE=true"\n                + " IRIS_26515_RENDER_EXPOSURE_AUTHORITY_SPLIT=true"\n'''
assert s.count(old)==1
s=s.replace(old,new)
p.write_text(s)

# Matcher: preserve full candidate tail, solve against exact render model, publish tone decision.
p=root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2ViewfinderExposureMatcher.java'
s=p.read_text()
s=s.replace('''    private static final float OUTPUT_EXPOSURE_SCALE = 0.80f;\n''','''    private static final float OUTPUT_EXPOSURE_SCALE = MotionV2Render.OUTPUT_EXPOSURE_SCALE;\n''',1)
s=s.replace('''    private float iris26550CandidateP99Guide = Float.NaN;\n''','''    private float iris26550CandidateP99Guide = Float.NaN;\n    private float iris26582CandidateP95Guide = Float.NaN;\n    private final ArrayList<Float> iris26582CandidateGuides = new ArrayList<>();\n''',1)
# reset tone state at Run entry
anchor='''        WorkingTexture = previousNode.WorkingTexture;\n        MotionViewfinderMetering.Snapshot snapshot = MotionViewfinderMetering.consumeLatest();\n'''
insert='''        WorkingTexture = previousNode.WorkingTexture;\n        iris26582CandidateGuides.clear();\n        iris26582CandidateP95Guide = Float.NaN;\n        iris26550CandidateP99Guide = Float.NaN;\n        basePipeline.mParameters.motionV2ToneP95Guide = Float.NaN;\n        basePipeline.mParameters.motionV2ToneP99Guide = Float.NaN;\n        basePipeline.mParameters.motionV2TonePredictedClipFraction = 0.0f;\n        basePipeline.mParameters.motionV2ToneBaseSceneWhite = 1.0f;\n        basePipeline.mParameters.motionV2ToneAdaptiveSceneWhite = 1.0f;\n        basePipeline.mParameters.motionV2ToneAdaptiveStrength = 0.0f;\n        MotionViewfinderMetering.Snapshot snapshot = MotionViewfinderMetering.consumeLatest();\n'''
assert s.count(anchor)==1
s=s.replace(anchor,insert)
# After final gain, publish decision
old='''            basePipeline.mParameters.motionV2DisplayGain = gain;\n            valid = true;\n\n            Log.i(Name, "IRIS_26519_VIEWFINDER_MATCH"\n'''
new='''            basePipeline.mParameters.motionV2DisplayGain = gain;\n            ToneDecision iris26582Tone = iris26582ToneDecision(gain);\n            basePipeline.mParameters.motionV2ToneP95Guide = iris26582CandidateP95Guide;\n            basePipeline.mParameters.motionV2ToneP99Guide = iris26550CandidateP99Guide;\n            basePipeline.mParameters.motionV2TonePredictedClipFraction = iris26582Tone.clippedFraction;\n            basePipeline.mParameters.motionV2ToneBaseSceneWhite = iris26582Tone.baseSceneWhite;\n            basePipeline.mParameters.motionV2ToneAdaptiveSceneWhite = iris26582Tone.adaptiveSceneWhite;\n            basePipeline.mParameters.motionV2ToneAdaptiveStrength = iris26582Tone.adaptiveStrength;\n            valid = true;\n\n            Log.i(Name, "IRIS_26582_SCENE_ADAPTIVE_TONE_DECISION"\n                    + " p95Guide=" + iris26582CandidateP95Guide\n                    + " p99Guide=" + iris26550CandidateP99Guide\n                    + " displayGain=" + gain\n                    + " predictedClipFraction=" + iris26582Tone.clippedFraction\n                    + " baseSceneWhite=" + iris26582Tone.baseSceneWhite\n                    + " adaptiveSceneWhite=" + iris26582Tone.adaptiveSceneWhite\n                    + " adaptiveStrength=" + iris26582Tone.adaptiveStrength\n                    + " highlightTarget=" + MotionV2Render.IRIS_26582_HIGHLIGHT_TARGET\n                    + " localTone=false uniformRgbScalar=true chromaOwnerUnchanged=true");\n\n            Log.i(Name, "IRIS_26519_VIEWFINDER_MATCH"\n'''
assert s.count(old)==1
s=s.replace(old,new)
# Candidate guide collection: replace night-only block
old='''            if (basePipeline.mParameters.irisNightActive && !all.isEmpty()) {\n                ArrayList<Float> guides = new ArrayList<>(all.size());\n                for (RgbSample s : all) guides.add(Math.max(s.r, Math.max(s.g, s.b)));\n                Collections.sort(guides);\n                int p99 = Math.max(0, Math.min(guides.size() - 1,\n                        Math.round((guides.size() - 1) * 0.99f)));\n                iris26550CandidateP99Guide = guides.get(p99);\n            }\n'''
new='''            if (!all.isEmpty()) {\n                iris26582CandidateGuides.clear();\n                for (RgbSample s : all) {\n                    iris26582CandidateGuides.add(Math.max(s.r, Math.max(s.g, s.b)));\n                }\n                Collections.sort(iris26582CandidateGuides);\n                int p95 = Math.max(0, Math.min(iris26582CandidateGuides.size() - 1,\n                        Math.round((iris26582CandidateGuides.size() - 1) * 0.95f)));\n                int p99 = Math.max(0, Math.min(iris26582CandidateGuides.size() - 1,\n                        Math.round((iris26582CandidateGuides.size() - 1) * 0.99f)));\n                iris26582CandidateP95Guide = iris26582CandidateGuides.get(p95);\n                iris26550CandidateP99Guide = iris26582CandidateGuides.get(p99);\n            }\n'''
assert s.count(old)==1
s=s.replace(old,new)
# exposureError and presentedLuma exact render model
old='''    private static float exposureError(ArrayList<RgbSample> samples, float ev, float targetLog) {\n        float gain = (float)Math.pow(2.0, ev);\n        ArrayList<Float> logs = new ArrayList<>(samples.size());\n        for (RgbSample sample : samples) {\n            logs.add(log2(Math.max(presentedLuma(sample, gain), 1.0e-5f)));\n        }\n        Collections.sort(logs);\n        return medianSorted(logs) - targetLog;\n    }\n\n    private static float solveBounded(ArrayList<RgbSample> samples, float targetLog,\n'''
new='''    private float exposureError(ArrayList<RgbSample> samples, float ev, float targetLog) {\n        float gain = (float)Math.pow(2.0, ev);\n        ToneDecision tone = iris26582ToneDecision(gain);\n        ArrayList<Float> logs = new ArrayList<>(samples.size());\n        for (RgbSample sample : samples) {\n            logs.add(log2(Math.max(presentedLuma(sample, gain, tone.adaptiveSceneWhite), 1.0e-5f)));\n        }\n        Collections.sort(logs);\n        return medianSorted(logs) - targetLog;\n    }\n\n    private float solveBounded(ArrayList<RgbSample> samples, float targetLog,\n'''
assert s.count(old)==1
s=s.replace(old,new)
start=s.index('''    private static float presentedLuma(RgbSample sample, float gain) {''')
end=s.index('''    private static float srgbDecode(float x) {''',start)
replacement='''    private static final class ToneDecision {\n        final float baseSceneWhite;\n        final float adaptiveSceneWhite;\n        final float clippedFraction;\n        final float adaptiveStrength;\n        ToneDecision(float baseSceneWhite, float adaptiveSceneWhite,\n                     float clippedFraction, float adaptiveStrength) {\n            this.baseSceneWhite = baseSceneWhite;\n            this.adaptiveSceneWhite = adaptiveSceneWhite;\n            this.clippedFraction = clippedFraction;\n            this.adaptiveStrength = adaptiveStrength;\n        }\n    }\n\n    private ToneDecision iris26582ToneDecision(float gain) {\n        float baseWhite = MotionV2Render.iris26582BaseSceneWhite(gain);\n        float clippedFraction = 0.0f;\n        if (!iris26582CandidateGuides.isEmpty()) {\n            float sourceThreshold = baseWhite / Math.max(gain, 1.0e-6f);\n            int lo = 0, hi = iris26582CandidateGuides.size();\n            while (lo < hi) {\n                int mid = (lo + hi) >>> 1;\n                if (iris26582CandidateGuides.get(mid) < sourceThreshold) lo = mid + 1;\n                else hi = mid;\n            }\n            clippedFraction = (iris26582CandidateGuides.size() - lo)\n                    / (float)iris26582CandidateGuides.size();\n        }\n        float adaptiveWhite = MotionV2Render.iris26582AdaptiveSceneWhite(\n                gain, iris26550CandidateP99Guide, clippedFraction);\n        float strength = MotionV2Render.iris26582AdaptiveStrength(clippedFraction);\n        if (adaptiveWhite <= baseWhite + 1.0e-6f) strength = 0.0f;\n        return new ToneDecision(baseWhite, adaptiveWhite, clippedFraction, strength);\n    }\n\n    /* IRIS_26582_SOLVER_RENDER_TONE_PARITY\n     * Exact scalar tone/gamut model used by motionv2/render.glsl. The removed 26581\n     * neutral-to-white and overflow-to-white solver approximations were stale and were not\n     * present in the final renderer.\n     */\n    private static float presentedLuma(RgbSample sample, float gain, float sceneWhite) {\n        float r = Math.max(0.0f, sample.r * gain);\n        float g = Math.max(0.0f, sample.g * gain);\n        float b = Math.max(0.0f, sample.b * gain);\n        float y = luma(r, g, b);\n        float peak = Math.max(r, Math.max(g, b));\n        float guide = Math.max(y, peak);\n        if (guide > 1.0e-7f) {\n            float mappedGuide = MotionV2Render.iris26582MapHeadroom(guide, sceneWhite);\n            float scale = mappedGuide / guide;\n            r *= scale;\n            g *= scale;\n            b *= scale;\n        }\n        r *= OUTPUT_EXPOSURE_SCALE;\n        g *= OUTPUT_EXPOSURE_SCALE;\n        b *= OUTPUT_EXPOSURE_SCALE;\n        float outPeak = Math.max(r, Math.max(g, b));\n        if (outPeak > 1.0f) {\n            r /= outPeak;\n            g /= outPeak;\n            b /= outPeak;\n        }\n        return clamp(luma(r, g, b), 0.0f, 1.0f);\n    }\n\n'''
s=s[:start]+replacement+s[end:]
p.write_text(s)

# Version
p=root/'app/version.properties'
s=p.read_text()
s=s.replace('VERSION_NAME=0.9726581','VERSION_NAME=0.9726582')
s=s.replace('VERSION_BUILD=26581','VERSION_BUILD=26582')
p.write_text(s)
print('PASS transformed exact successful 26581 -> 26582 adaptive global tone candidate')
